const ACTOR_ID='soc9WktXbQXtS30Ra';
const BUSINESS_TAB='Allegro Current',HISTORY_TAB='Allegro History',RUN_TAB='Allegro Runs',LOCK_TAB='_ALLEGRO_WORKFLOW_LOCK';
const MAX_EXISTING=5000,MAX_DATASET=1000;
const BUSINESS_HEADERS=['offerKey','offerId','title','sourceUrl','price','currency','sellerName','firstSeenAt','lastSeenAt','lastRunId','previousPrice','priceChange','priceChangePercent','observationType','inputUrl'];
const HISTORY_HEADERS=['observationKey','runId','offerKey','offerId','title','price','currency','observedAt','previousPrice','priceChange','priceChangePercent','observationType','sourceUrl','inputUrl'];
const RUN_HEADERS=['runId','status','inputUrl','maxItemsPerUrl','currency','startedAt','finishedAt','datasetId','rowsRead','rowsRejected','rowsAdded','rowsUpdated','duplicatesSkipped','estimatedResultChargeUsd','maxChargeUsd','buildNumber','executionId','notes'];
function listingUrl(value){
 const s=String(value??'').trim();
 if(!/^https:\/\/allegro\.pl\/(?:kategoria\/[^\s#]+|uzytkownik\/[^\s#]+|listing\?[^\s#]+)$/.test(s))throw new Error('Use one HTTPS allegro.pl category, seller, or search listing URL; this template supports PLN only.');
 return s;
}
function config(input){
 const c={...input};c.searchUrl=listingUrl(c.searchUrl);c.spreadsheetId=String(c.spreadsheetId??'').trim();c.resumeRunId=String(c.resumeRunId??'').trim();
 if(!/^[A-Za-z0-9_-]{20,100}$/.test(c.spreadsheetId))throw new Error('Paste the spreadsheet ID (not its URL) in Configure search before starting a paid run.');
 if(c.resumeRunId&&!/^[A-Za-z0-9]{17}$/.test(c.resumeRunId))throw new Error('resumeRunId must be the 17-character Apify run ID.');
 c.maxItemsPerUrl=Number(c.maxItemsPerUrl);c.maxChargeUsd=Number(c.maxChargeUsd);
 if(!Number.isInteger(c.maxItemsPerUrl)||c.maxItemsPerUrl<1||c.maxItemsPerUrl>100)throw new Error('maxItemsPerUrl must be an integer from 1 to 100.');
 if(!Number.isFinite(c.maxChargeUsd)||c.maxChargeUsd<0.01||c.maxChargeUsd>1)throw new Error('maxChargeUsd must be between 0.01 and 1 USD.');
 return c;
}
function originalInput(input){
 if(!Array.isArray(input?.searchUrls)||input.searchUrls.length!==1)throw new Error('Recovery requires a run with exactly one Polish listing URL.');
 listingUrl(input.searchUrls[0]);
 if(!Number.isInteger(input.maxItemsPerUrl)||input.maxItemsPerUrl<1||input.maxItemsPerUrl>100)throw new Error('Recovery run must specify maxItemsPerUrl between 1 and 100.');
 return input;
}
function prepareSheet(meta){
 if(!Array.isArray(meta.sheets))throw new Error('Cannot read spreadsheet tabs. Check Google Sheets credentials.');
 const names=meta.sheets.map(s=>s.properties.title);
 if(names.includes(LOCK_TAB))throw new Error('Allegro destination is locked. Check active executions and Allegro Runs. Only when none is active, delete _ALLEGRO_WORKFLOW_LOCK and resume the saved run ID.');
 const requests=[{addSheet:{properties:{title:LOCK_TAB,gridProperties:{rowCount:5,columnCount:2}}}}];
 for(const title of [BUSINESS_TAB,HISTORY_TAB,RUN_TAB])if(!names.includes(title))requests.push({addSheet:{properties:{title,gridProperties:{rowCount:MAX_EXISTING+2,columnCount:20}}}});
 return {requests};
}
function validateTable(values,headers,label){
 if(!values?.length)return [];
 if(headers.some((h,i)=>values[0]?.[i]!==h))throw new Error(label+' headers do not match the template. Restore managed columns before starting paid work.');
 const rows=values.slice(1);if(rows.length>MAX_EXISTING)throw new Error(label+' exceeds 5000 rows. Archive and start a new spreadsheet.');
 const keys=new Set();for(const r of rows){if(!r[0]||keys.has(String(r[0])))throw new Error(label+' contains missing or duplicate keys. Restore the table before running.');keys.add(String(r[0]));}
 return rows;
}
function checkRun(run){
 if(run.actId!==ACTOR_ID)throw new Error('Recovery run belongs to another Actor. Use Allegro Listings Scraper.');
 if(['FAILED','ABORTED','TIMED-OUT'].includes(run.status))throw new Error('Apify run '+run.id+' ended '+run.status+'. No price observations written. Inspect its log.');
 if(!['READY','RUNNING','TIMING-OUT','ABORTING','SUCCEEDED'].includes(run.status))throw new Error('Unsupported Actor status: '+run.status);
 return run.status==='SUCCEEDED';
}
function checkDataset(meta){
 if(!Number.isInteger(meta.itemCount)||meta.itemCount<=0)throw new Error('No Allegro rows returned. Inspect the Actor log: an empty extraction is not evidence that offers disappeared.');
 if(meta.itemCount>MAX_DATASET)throw new Error('Dataset exceeds the 1000-row safety bound; no silent truncation.');return meta.itemCount;
}
function normalize(item){
 if(!item||typeof item.label!=='string'||!item.label.trim()||typeof item.link!=='string')return null;
 if(typeof item.price!=='number'||!Number.isFinite(item.price)||item.price<=0||item.price>1+1234567890||item.currency!=='PLN')return null;
 // Identity must be an explicit offer ID, never a product UUID or a title.
 const direct=item.link.match(/^https:\/\/allegro\.pl\/oferta\/[^?#\s]+-(\d{5,20})(?:[?#]|$)/);
 const product=item.link.match(/^https:\/\/allegro\.pl\/produkt\/[^?#\s]+\?(?:[^#\s]*&)?offerId=(\d{5,20})(?:&|#|$)/);
 const offerId=direct?.[1]??product?.[1];if(!offerId)return null;
 const price=Math.round(item.price*100)/100;if(price<=0)return null;
 return {key:'allegro.pl:'+offerId+':PLN',offerId,title:item.label.trim().slice(0,2000),url:item.link,price,currency:'PLN',seller:String(item.sellerName??'').slice(0,500)};
}
function ledgerRow(ctx,status,counts={},notes=''){
 const {run,input,executionId}=ctx;const e=run.pricingInfo?.pricingPerEvent?.actorChargeEvents?.['apify-default-dataset-item'];
 const n=typeof counts.read==='number'?Math.min(counts.read,run.options?.maxItems??counts.read):undefined;
 const estimate=typeof e?.eventPriceUsd==='number'&&n!==undefined?Math.round(e.eventPriceUsd*n*1e8)/1e8:'';
 return [run.id,status,input.searchUrls[0],input.maxItemsPerUrl,'PLN',run.startedAt,run.finishedAt??'',run.defaultDatasetId,counts.read??'',counts.rejected??'',counts.added??'',counts.updated??'',counts.duplicates??'',estimate,run.options?.maxTotalChargeUsd??'',run.buildNumber??'',String(executionId),notes];
}
function planWrites(ctx,items,existing,ledger,datasetCount,history=[]){
 if(!Array.isArray(items)||items.length!==datasetCount)throw new Error('Dataset retrieval is incomplete. No observations written.');
 originalInput(ctx.input);checkDataset({itemCount:items.length});
 const time=ctx.run.finishedAt;if(!time||!Number.isFinite(Date.parse(time)))throw new Error('Completed run timestamp missing.');
 const oldMap=new Map(existing.map((r,i)=>[r[0],{row:r,index:i+2}]));const histKeys=new Set(history.map(r=>r[0]));
 // Reject out-of-order recovery: otherwise previous-price comparisons could be misleading.
 for(const r of existing){if(!Number.isFinite(Date.parse(r[8])))throw new Error('Invalid lastSeenAt in current table.');if(Date.parse(r[8])>Date.parse(time))throw new Error('This run predates existing observations. Import it into a separate spreadsheet to preserve chronological price history.');}
 const unique=new Map(),conflicts=new Set();const counts={read:items.length,rejected:0,duplicates:0,added:0,updated:0,unchanged:0,historyAdded:0,priceChanges:0,baselines:0};
 for(const item of items){const n=normalize(item);if(!n){counts.rejected++;continue;}if(unique.has(n.key)){counts.duplicates++;if(unique.get(n.key).price!==n.price)conflicts.add(n.key);}else unique.set(n.key,n);}
 for(const key of conflicts){unique.delete(key);counts.rejected++;}
 if(!unique.size)throw new Error('No valid, unambiguous PLN offer prices. Possible schema drift; no price observations written.');
 const data=[{range:`'${BUSINESS_TAB}'!A1:O1`,values:[BUSINESS_HEADERS]},{range:`'${HISTORY_TAB}'!A1:N1`,values:[HISTORY_HEADERS]},{range:`'${RUN_TAB}'!A1:R1`,values:[RUN_HEADERS]}];
 let next=existing.length+2,hnext=history.length+2;
 for(const n of unique.values()){
  const old=oldMap.get(n.key),r=old?.row;const hk=ctx.run.id+':'+n.key;
  if(r?.[9]===ctx.run.id){if(!histKeys.has(hk))throw new Error('Current observation has no matching history row. Restore history before replay.');counts.unchanged++;continue;}
  if(histKeys.has(hk))throw new Error('History already contains this run but current state disagrees. Restore current state before replay.');
  if(r&&Date.parse(r[8])===Date.parse(time))throw new Error('Two different runs have the same observation timestamp. Review before comparison.');
  let prev='',delta='',percent='',type='BASELINE';
  if(r){if(r[5]!==n.currency||typeof r[4]!=='number'||!Number.isFinite(r[4])||r[4]<=0)throw new Error('Invalid previous price or currency in current table; restore it before comparing.');prev=r[4];delta=Math.round((n.price-prev)*100)/100;percent=Math.round(delta/prev*10000)/100;type=delta===0?'UNCHANGED':delta>0?'INCREASE':'DECREASE';}
  if(type==='BASELINE')counts.baselines++;if(type==='INCREASE'||type==='DECREASE')counts.priceChanges++;
  const row=old?.index??next++;if(row>MAX_EXISTING+1||hnext>MAX_EXISTING+1)throw new Error('Current/history table is full. Archive and start a new spreadsheet.');
  data.push({range:`'${BUSINESS_TAB}'!A${row}:O${row}`,values:[[n.key,n.offerId,n.title,n.url,n.price,n.currency,n.seller,r?.[7]||time,time,ctx.run.id,prev,delta,percent,type,ctx.input.searchUrls[0]]]});
  data.push({range:`'${HISTORY_TAB}'!A${hnext}:N${hnext}`,values:[[hk,ctx.run.id,n.key,n.offerId,n.title,n.price,n.currency,time,prev,delta,percent,type,n.url,ctx.input.searchUrls[0]]]});hnext++;counts.historyAdded++;if(old)counts.updated++;else counts.added++;
 }
 const found=ledger.findIndex(r=>r[0]===ctx.run.id),ri=found>=0?found+2:ledger.length+2;if(ri>MAX_EXISTING+1)throw new Error('Run log is full.');
 const status=counts.rejected?'PARTIAL_ROWS_REJECTED':'IMPORTED';const notes=`${counts.historyAdded} observations; ${counts.baselines} baselines; ${counts.priceChanges} price changes; ${counts.unchanged} replayed. Missing offers are not observed, not sold out. Prices exclude delivery; no product matching or FX conversion.`;
 if(!(found>=0&&['IMPORTED','PARTIAL_ROWS_REJECTED'].includes(ledger[found][1])))data.push({range:`'${RUN_TAB}'!A${ri}:R${ri}`,values:[ledgerRow(ctx,status,counts,notes)]});
 return {body:{valueInputOption:'RAW',data},summary:{status,runId:ctx.run.id,datasetId:ctx.run.defaultDatasetId,...counts,notes}};
}

return [{json:config($json)}];

